/**
 * Raven61 physical layout: ANSI 60 %, 61 keys, 15u x 5u.
 *
 * GENERATED by tools/layout/from-vendor-xml.mjs from the stock driver's
 * layouts/Raven61.xml — do not hand-edit; re-run the generator instead.
 *
 * - `index`     this file's ordering (row-major, left to right); what the UI uses.
 * - `keyIndex`  the FIRMWARE's key address, used in every protocol command.
 *               It is not contiguous and does not follow the visual order:
 *               Backspace is 92, Enter 76, Menu 109.
 * - `lightIndex` per-key LED address. Mostly equal to keyIndex; the vendor XML
 *               lists 37 for both "-" and "T", which looks like their bug.
 */
export interface KeyDef {
  index: number
  label: string
  /** Default HID Keyboard/Keypad (page 0x07) usage id. 0xff = Fn, no HID code. */
  code: number
  /** Position in keyboard units from the top-left. */
  x: number
  y: number
  w: number
  /** Firmware key address — the value the board expects in commands. */
  keyIndex: number
  /** Per-key LED address. */
  lightIndex: number
}

