export const KEY_COUNT = RAVEN61_KEYS.length
export const LAYOUT_UNITS = { width: 15, height: 5 }

/** Full travel, in mm. Confirmed on hardware: every key event reports 200 counts. */
export const DEFAULT_TRAVEL_MM = 4.0

export function keyByIndex(index: number): KeyDef | undefined {
  return RAVEN61_KEYS[index]
}

const BY_KEY_INDEX = new Map(RAVEN61_KEYS.map((k) => [k.keyIndex, k]))
const BY_USAGE = new Map(RAVEN61_KEYS.map((k) => [k.code, k]))

/** Maps a firmware key address back to a physical key. */
export function keyByFirmwareIndex(keyIndex: number): KeyDef | undefined {
  return BY_KEY_INDEX.get(keyIndex)
}

/**
 * Maps a HID usage back to a physical key. The firmware addresses keys this way
 * in its analog events and in the stock driver's database, while `keyIndex` is
 * used elsewhere — the two are not interchangeable.
 */
export function keyByUsage(code: number): KeyDef | undefined {
  return BY_USAGE.get(code)
}
